// ---- certificate border
function cert(a) {
  if (a.style !== undefined && !STYLES.includes(a.style)) return err("style must be one of: " + STYLES.join(", ") + ".");
  if (a.paper !== undefined && !PAPERS.includes(a.paper)) return err("paper must be one of: " + PAPERS.join(", ") + ".");
  if (a.scheme !== undefined && !SCHEMES.includes(a.scheme)) return err("scheme must be one of: " + SCHEMES.join(", ") + ".");
  if (a.seal !== undefined && !SEALS.includes(a.seal)) return err("seal must be one of: " + SEALS.join(", ") + ".");
  for (const k of ["color", "color2"]) if (a[k] !== undefined && !HEX.test(String(a[k]))) return err(k + " must be #rrggbb.");
  if (a.margin !== undefined && !(fin(a.margin) && num(a.margin) >= 0 && num(a.margin) <= 60)) return err("margin must be 0-60 mm.");
  if (a.band !== undefined && !(fin(a.band) && num(a.band) >= 4 && num(a.band) <= 40)) return err("band must be 4-40 mm.");
  if (typeof a.title === "string" && a.title.length > 80) return err("title must be at most 80 characters.");
  const o = { style: a.style || "banknote", paper: a.paper || "letter", orient: a.orient === "portrait" ? "portrait" : "landscape", scheme: a.scheme || "navy", seal: a.seal || "star" };
  if (a.scheme === "custom") { o.color = a.color || "#1d2f5c"; o.color2 = a.color2 || "#b8923a"; }
  if (fin(a.margin)) o.margin = num(a.margin);
  if (fin(a.band)) o.band = num(a.band);
  if (["bottom", "right", "left"].includes(a.seal_pos)) o.sealPos = a.seal_pos;
  if (typeof a.title === "string") o.title = str(a.title, 80);
  if (typeof a.subtitle === "string") o.subtitle = str(a.subtitle, 120);
  if (fin(a.signatures)) o.sig = Math.max(0, Math.min(2, Math.round(num(a.signatures))));
  const r = C.build(o), page = `${T}/certificate-border/`, inner = r.inner, seal = r.seal;
  const pp = C.PAPER[o.paper], name = C.STYLES.find((s) => s[0] === r.style);
  const box = { x: r1(inner.x), y: r1(inner.y), w: r1(inner.w), h: r1(inner.h) };
  const lines = [`**${name[1]} certificate border, ${pp[2]} ${o.orient}: page ${r1(r.W)} × ${r1(r.H)} mm; blank writing area ${box.w} × ${box.h} mm at (${box.x}, ${box.y}) mm from the top-left${seal ? `; ${seal.kind} seal centred at (${r1(seal.cx)}, ${r1(seal.cy)}) mm, radius ${r1(seal.r)} mm` : ""}.**`, name[2] + "."];
  if (r.warnings && r.warnings.length) lines.push("Note: " + r.warnings.join(" "));
  const sc = { style: r.style, paper: o.paper, orient: o.orient, page_mm: { w: r1(r.W), h: r1(r.H) }, inner_mm: box, seal_mm: seal ? { cx: r1(seal.cx), cy: r1(seal.cy), r: r1(seal.r), kind: seal.kind } : null, warnings: r.warnings || [], page };
  if (a.format !== "none") {
    const svg = C.svg(r, o.title || "Certificate border").replace(/ d="[^"]*"/g, (m) => m.replace(/-?\d+\.\d+/g, (n) => String(r1(+n))));   // 0.1 mm is far below print resolution
    if (svg.length <= OUT_CAP) { lines.push(`True-size SVG (${Math.round(svg.length / 1024)} KB, mm units):`, fence("svg", svg)); sc.svg = svg; }
    else { lines.push(`The ${r.style} border's fine line work is ${Math.round(svg.length / 1024)} KB as SVG, too large to return inline: download it (PDF/SVG/PNG) from the page. Styles that fit inline: ornate, deco, classic, ropewave.`); sc.svg_too_large = true; }
  }
  lines.push("Print at 100% (actual size). Live preview, PDF and 300 DPI PNG: " + page);
  return ok(lines.join("\n"), sc);
}

// ---- kitchen work triangle
const TRI = PB.TRI;
function pt(v, k) { return Array.isArray(v) && v.length >= 2 && fin(v[0]) && fin(v[1]) ? [num(v[0]) * k, num(v[1]) * k] : null; }
function triangle(a) {
  const u = UNITS[a.unit] ? a.unit : "m", k = UNITS[u];
  let legs, pts = null, cross = [0, 0, 0];
  if (Array.isArray(a.legs)) {
    if (a.legs.length !== 3 || !a.legs.every((x) => fin(x) && num(x) > 0)) return err("legs must be three positive lengths: [sink-cooktop, cooktop-fridge, fridge-sink].");
    legs = a.legs.map((x) => num(x) * k);
    const [p, q, s] = legs; if (p + q < s - 1e-6 || q + s < p - 1e-6 || s + p < q - 1e-6) return err("Those three legs cannot form a triangle (one leg is longer than the other two together).");
  } else {
    pts = [pt(a.sink, k), pt(a.cooktop, k), pt(a.fridge, k)];
    if (pts.some((x) => !x)) return err("Give legs, or sink, cooktop and fridge as [x, y] positions.");
    legs = [[0, 1], [1, 2], [2, 0]].map(([i, j]) => Math.hypot(pts[i][0] - pts[j][0], pts[i][1] - pts[j][1]));
    if (Array.isArray(a.islands)) {
      if (a.islands.length > 4) return err("At most 4 islands.");
      for (const isl of a.islands) {
        if (!Array.isArray(isl) || isl.length < 4 || !isl.slice(0, 4).every(fin) || num(isl[2]) <= 0 || num(isl[3]) <= 0) return err("islands must be [x, y, width, depth] with positive width and depth.");
        const [x, y, w, d] = isl.slice(0, 4).map((v) => num(v) * k), pg = [[x, y], [x + w, y], [x + w, y + d], [x, y + d]];
        [[0, 1], [1, 2], [2, 0]].forEach(([i, j], n) => { cross[n] = Math.max(cross[n], PB.clipLen(pts[i], pts[j], pg)); });
      }
    }
  }
  const names = ["Sink to cooktop", "Cooktop to fridge", "Fridge to sink"], sum = legs[0] + legs[1] + legs[2], issues = [];
  legs.forEach((l, i) => { if (l < TRI.min - 0.5) issues.push(`${names[i]} ${fmtLen(l, u)} is shorter than ${fmtLen(TRI.min, u)}.`); if (l > TRI.max + 0.5) issues.push(`${names[i]} ${fmtLen(l, u)} is longer than ${fmtLen(TRI.max, u)}.`); });
  if (sum < TRI.sumMin - 0.5) issues.push(`Total ${fmtLen(sum, u)} is under ${fmtLen(TRI.sumMin, u)} (cramped).`);
  if (sum > TRI.sumMax + 0.5) issues.push(`Total ${fmtLen(sum, u)} is over ${fmtLen(TRI.sumMax, u)} (too much walking).`);
  cross.forEach((c, i) => { if (c > TRI.island + 0.5) issues.push(`${names[i]} cuts through an island by ${fmtLen(c, u)} (limit ${fmtLen(TRI.island, u)}).`); });
  let aisle = null;
  if (a.aisle !== undefined) {
    if (!(fin(a.aisle) && num(a.aisle) > 0)) return err("aisle must be a positive length.");
    const need = num(a.cooks) >= 2 ? 1220 : 1070, have = num(a.aisle) * k;
    aisle = { width_mm: r1(have), min_mm: need, ok: have >= need - 0.5 };
    if (!aisle.ok) issues.push(`Work aisle ${fmtLen(have, u)} is narrower than ${fmtLen(need, u)} for ${need === 1220 ? "two cooks" : "one cook"}.`);
  }
  const page = `${T}/kitchen-planner/`, okAll = !issues.length;
  const lines = [`**Work triangle: ${names.map((n, i) => `${n.toLowerCase()} ${fmtLen(legs[i], u)}`).join(", ")}; total ${fmtLen(sum, u)} — ${okAll ? "within the guideline" : issues.length + " issue" + (issues.length > 1 ? "s" : "")}.**`];
  if (!okAll) lines.push(...issues.map((x) => "- " + x));
  lines.push(`Guideline (NKBA Kitchen Planning Guidelines): each leg ${fmtLen(TRI.min, u)}–${fmtLen(TRI.max, u)}, total ${fmtLen(TRI.sumMin, u)}–${fmtLen(TRI.sumMax, u)}, an island or peninsula may cut a leg by at most ${fmtLen(TRI.island, u)}; work aisles ${fmtLen(1070, u)} (one cook) / ${fmtLen(1220, u)} (two). Legs are measured between the centre-fronts of the sink, cooktop and fridge.`);
  lines.push("Draw it to scale with cabinets and clearances: " + page);
  return ok(lines.join("\n"), { unit: u, legs: legs.map((l) => r2(l / k)), legs_mm: legs.map(r1), total: r2(sum / k), total_mm: r1(sum), island_cut_mm: cross.map(r1), aisle, ok: okAll, issues, guideline_mm: { leg_min: TRI.min, leg_max: TRI.max, total_min: TRI.sumMin, total_max: TRI.sumMax, island_max: TRI.island }, page });
}

// ---- square-foot garden
function garden(a) {
  const u = ["ft", "in", "m", "cm"].includes(a.unit) ? a.unit : "ft", k = UNITS[u], grid = a.grid === "metric" ? "metric" : "ft";
  const w = fin(a.width) ? num(a.width) : u === "ft" ? 4 : u === "in" ? 48 : u === "m" ? 1.2 : 120, l = fin(a.length) ? num(a.length) : u === "ft" ? 8 : u === "in" ? 96 : u === "m" ? 2.4 : 240;
  if (!(w > 0 && l > 0) || w * k > 30000 || l * k > 30000) return err("width and length must be positive and at most 30 m (98 ft).");
  const s = PB.sq(grid === "ft" ? "ft" : "m"), nx = Math.floor(w * k / s + 1e-6), ny = Math.floor(l * k / s + 1e-6), total = nx * ny;
  if (!total) return err(`The bed is smaller than one ${grid === "ft" ? "1 ft" : "30 cm"} square.`);
  const list = Array.isArray(a.crops) ? a.crops.slice(0, 40) : [];
  for (const c of list) {
    if (!c || !CROPS.includes(c.crop)) return err("crop must be one of: " + CROPS.join(", ") + ".");
    if (c.squares !== undefined && !(Number.isInteger(num(c.squares)) && num(c.squares) >= 1)) return err("squares must be a whole number ≥ 1.");
  }
  const fixed = list.reduce((x, c) => x + (c.squares !== undefined ? num(c.squares) : 0), 0);
  if (fixed > total) return err(`The crops ask for ${fixed} squares but the bed has ${total}.`);
  const auto = list.filter((c) => c.squares === undefined), share = auto.length ? Math.floor((total - fixed) / auto.length) : 0;
  const rows = list.map((c) => {
    const def = PB.CROPS.find((x) => x[0] === c.crop), sqn = c.squares !== undefined ? num(c.squares) : share, per = def[2];
    return { crop: c.crop, label: def[1], squares: sqn, per_square: per < 1 ? "1 per 9 squares" : per, plants: per >= 1 ? sqn * per : Math.floor(sqn / 9) };
  });
  const used = rows.reduce((x, r) => x + r.squares, 0), layout = [];
  let cursor = 0; for (const r of rows) { for (let i = 0; i < r.squares; i++, cursor++) layout.push({ row: Math.floor(cursor / nx) + 1, col: (cursor % nx) + 1, crop: r.crop }); }
  const page = `${T}/garden-planner/`, sqLabel = grid === "ft" ? "1 ft (30.48 cm)" : "30 cm";
  const lines = [`**${w} × ${l} ${u} bed = ${nx} × ${ny} = ${total} squares of ${sqLabel}${rows.length ? `; ${used} planted, ${total - used} free` : ""}.**`];
  if (rows.length) lines.push("| Crop | Squares | Per square | Plants |", "|---|---|---|---|", ...rows.map((r) => `| ${r.label} | ${r.squares} | ${r.per_square} | ${r.plants} |`));
  else lines.push("Plants per square: " + PB.CROPS.map((c) => `${c[1]} ${c[2] < 1 ? "1/9" : c[2]}`).join(", ") + ".");
  if (rows.some((r) => r.crop === "squash" && r.squares % 9)) lines.push("Note: squash needs 9 squares (3 × 3) per plant; leftover squares in its share hold no squash.");
  lines.push("Spacing follows the square-foot gardening method (1, 4, 9 or 16 plants per square by mature size); tall crops on the north side. Draw beds and paths to scale: " + page);
  return ok(lines.join("\n"), { width: w, length: l, unit: u, grid, square_mm: s, cols: nx, rows: ny, squares: total, planted: used, free: total - used, crops: rows, layout: layout.length <= 600 ? layout : [], page });
}

const HANDLERS = { make_certificate_border: cert, calc_kitchen_work_triangle: triangle, plan_square_foot_garden: garden };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools68Tool(name) { return NAMES.has(name); }
export async function callTools68Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
